// Build today's per-source summary from both sheets.
const TZ = 'Asia/Jerusalem';
const today = new Date().toLocaleDateString('en-CA', { timeZone: TZ });
const SOURCES = ['google', 'facebook', 'website', 'portal'];

const rows = (nodeName) =>
  $(nodeName).all().map((i) => i.json).filter((r) => r && r.lead_id && String(r.received_date) === today);

const all = [...rows('Read Leads'), ...rows('Read Rejected')];

const pct = (n, d) => (d ? Math.round((n / d) * 100) : 0);
const stats = (list) => {
  const count = list.length;
  const hot = list.filter((r) => r.quality === 'hot').length;
  const warm = list.filter((r) => r.quality === 'warm').length;
  const irrelevant = list.filter((r) => r.quality === 'irrelevant').length;
  return { count, hot, warm, irrelevant, pct_hot: pct(hot, count), pct_irrelevant: pct(irrelevant, count) };
};

const extraSources = [...new Set(all.map((r) => r.source))].filter((s) => !SOURCES.includes(s));
const bySource = [...SOURCES, ...extraSources].map((source) => ({
  source,
  ...stats(all.filter((r) => r.source === source)),
}));
const total = stats(all);

const lines = bySource
  .filter((s) => s.count > 0)
  .map((s) => '• ' + s.source + ': ' + s.count + ' leads · ' + s.pct_hot + '% hot · ' + s.pct_irrelevant + '% irrelevant');

const text = total.count
  ? ['📊 Daily lead summary — ' + today, '', ...lines, '',
     'Total: ' + total.count + ' · 🔥 ' + total.hot + ' hot · 🌤 ' + total.warm + ' warm · 🗑 ' + total.irrelevant + ' irrelevant'].join('\n')
  : '📊 Daily lead summary — ' + today + '\n\nNo new leads today.';

const td = (v) => '<td style="padding:6px 12px;border-bottom:1px solid #eee">' + v + '</td>';
const th = (v) => '<th style="padding:6px 12px;text-align:left;border-bottom:2px solid #333">' + v + '</th>';
const html =
  '<h2 style="font-family:sans-serif">Daily lead summary — ' + today + '</h2>' +
  '<table style="font-family:sans-serif;border-collapse:collapse">' +
  '<tr>' + ['Source', 'Leads', 'Hot', 'Warm', 'Irrelevant', '% hot', '% irrelevant'].map(th).join('') + '</tr>' +
  bySource.map((s) => '<tr>' + [s.source, s.count, s.hot, s.warm, s.irrelevant, s.pct_hot + '%', s.pct_irrelevant + '%'].map(td).join('') + '</tr>').join('') +
  '<tr style="font-weight:bold">' + ['Total', total.count, total.hot, total.warm, total.irrelevant, total.pct_hot + '%', total.pct_irrelevant + '%'].map(td).join('') + '</tr>' +
  '</table>';

return [{ json: { date: today, total, by_source: bySource, text, html } }];
